import { KAI_BRIEF, KAI, isKai } from './kai-brand.mjs';
import { mountAutopilot } from './autopilot.mjs';
import { generateIdeas, createProject, normalizeBrief, buildFlowPack, buildImagePrompt, buildAnimationPrompt, generationPlan, exportProjectMarkdown, buildCodexPrompt, toSrt, validateProject } from './planner.mjs';
import { drawFrame, sceneAt, dimensions, palette, clamp } from './motion.mjs';

const $=s=>document.querySelector(s), esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const icons={
  logo:'<path d="M3 20V4l9 10L21 4v16"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',plus:'<path d="M12 5v14M5 12h14"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',film:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M7 4v16M17 4v16M3 9h4m10 0h4M3 15h4m10 0h4"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',folder:'<path d="M3 6h7l2 3h9v11H3Z"/>',layers:'<path d="m12 3 10 6-10 6L2 9Zm-10 9 10 6 10-6M2 17l10 6 10-6"/>',play:'<path d="m7 4 14 8L7 20Z"/>',pause:'<path d="M6 4h4v16H6Zm8 0h4v16h-4Z"/>',safe:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5M8 8h8v8H8Z"/>',music:'<path d="M9 18V5l11-2v13M9 8l11-2"/><ellipse cx="5" cy="18" rx="4" ry="3"/><ellipse cx="16" cy="16" rx="4" ry="3"/>',mic:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 9v2a7 7 0 0 0 14 0V9m-7 9v4m-4 0h8"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',external:'<path d="M13 3h8v8m0-8L10 14m-1-9H3v16h16v-6"/>',file:'<path d="M14 2H4v20h16V8Zm0 0v6h6M8 12h8m-8 4h8"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',check:'<path d="m4 12 5 5L20 6"/>',undo:'<path d="M8 4 3 9l5 5m-5-5h12a6 6 0 0 1 0 12"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',left:'<path d="m14 5-7 7 7 7"/>',volume:'<path d="m11 4-6 5H2v6h3l6 5Zm4 4a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>'
};
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.spark}</svg>`;
const defaults={...KAI_BRIEF};
let project;
try {const saved=JSON.parse(localStorage.getItem('kai-project-v1'));if(saved&&validateProject(saved).length===0)project=saved;}catch{}
project ||= createProject(defaults);
project.brief.aspectRatio='9:16';
let draft={...project.brief},route='autopilot',selected=0,time=.85,playing=false,safeArea=false,captions=project.captions!==false;
let saved=true,saveTimer,toastTimer,health=null,exporting=false,cancelExport=false,renderJob=savedRender(project),renderStatus=null;
const cache=new Map(),audio={voice:null,music:null};
let unmountAutopilot=null;
const stages=[['autopilot','Produksi otomatis','Small ideas. Everyday stuff.','Codex menulis, Flow membuat footage, Kai Studio menyelesaikan editan.'],['brief','Brief & ide','Beri arah ceritamu.','Mulai dari barang sehari-hari dan satu kegunaan baru.'],['storyboard','Cerita & scene','Cerita yang terasa.','Susun material, proses yang masuk akal, lalu hasil yang dipakai.'],['flow','Generate di Flow','Bawa ceritamu ke Flow.','Prompt siap pakai, identitas visual tetap konsisten.'],['edit','Edit & audio','Susun. Rasakan. Rapikan.','Rapikan footage, teks, suara bahan, dan musik opsional.'],['export','Ekspor & publish','Siap untuk dilihat.','Render MP4 dan bawa semua materi publikasinya.']];
const styleNames={kai:'Kai · Little Makes',kinetic:'Kinetic type',cinematic:'Pop cinematic',editorial:'Editorial',stickman:'Stickman'};
const styleDescriptions={kai:'Warm home DIY · sound & texture',kinetic:'Tipografi & bentuk tegas',cinematic:'Kontras, depth & impact',editorial:'Tenang, rapi & bertekstur',stickman:'Karakter simpel & ekspresif'};
const total=()=>project.scenes.reduce((sum,s)=>sum+s.duration,0);
const sceneStart=index=>project.scenes.slice(0,index).reduce((sum,s)=>sum+s.duration,0);
const tc=t=>`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
const precise=t=>`${tc(t)}.${String(Math.floor(t%1*10))}`;
const scene=()=>project.scenes[selected];
const asset=id=>(project.assets||[]).find(a=>a.id===id);
function fingerprint(p){const {lastRender,updatedAt,...rest}=p;return JSON.stringify(rest);}
function savedRender(p){const r=p.lastRender;if(r?.status==='complete'&&typeof r.id==='string'&&/^[a-zA-Z0-9_-]{1,80}$/.test(r.id)&&r.url===`/api/renders/${r.id}/download`&&r.fingerprint===fingerprint(p))return r;return null;}
function toast(message,error=false){clearTimeout(toastTimer);const el=$('#toast');el.className=`toast${error?' error':''}`;el.textContent=message;toastTimer=setTimeout(()=>{el.className='';el.textContent='';},5000);}
async function api(url,options={}){const response=await fetch(url,options);let body;try{body=await response.json();}catch{throw Error('Server mengirim respons yang tidak valid.');}if(!response.ok)throw Error(body.error||`Server ${response.status}`);return body;}
const post=(url,data)=>api(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
function download(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
const slug=()=>project.title.toLowerCase().replace(/[^a-z0-9]+/g,'-').slice(0,65)||'kai-project-v1';
async function copy(value){try{await navigator.clipboard.writeText(value);toast('Tersalin. Siap ditempel.');}catch{showModal('Salin teks ini',`<textarea class="prompt-box" readonly style="max-height:none;height:330px">${esc(value)}</textarea>`);}}
function showModal(title,body){$('#modal-content').innerHTML=`<button class="icon-btn close" data-action="close-modal" aria-label="Tutup">${icon('close')}</button><h2>${esc(title)}</h2>${body}`;$('#modal').showModal();}
function modalClose(){if($('#modal').open)$('#modal').close();}
function markDirty(){saved=false;try{localStorage.setItem('kai-project-v1',JSON.stringify(project));}catch{toast('Penyimpanan browser penuh. Unduh JSON proyek untuk cadangan.',true);}updateSave();clearTimeout(saveTimer);saveTimer=setTimeout(()=>saveProject().catch(error=>{updateSave(error.message);}),650);}
function updateSave(error){const el=$('#save-state');if(el){el.innerHTML=`<i class="dot"${error?' style="background:#ffab8c"':''}></i>${error?'Tersimpan di browser':saved?'Tersimpan lokal':'Menyimpan…'}`;el.title=error||'Proyek disimpan di perangkat ini';}}
async function saveProject(){const errors=validateProject(project);if(errors.length)throw Error(errors[0]);const current=JSON.stringify(project);const result=await post('/api/projects',project);if(current===JSON.stringify(project)){project.updatedAt=result.project.updatedAt;saved=true;try{localStorage.setItem('kai-project-v1',JSON.stringify(project));}catch{}updateSave();}return result.project;}
function effectiveProject(){return route==='brief'?{...project,brief:{...project.brief,style:draft.style,accent:draft.accent,aspectRatio:draft.aspectRatio}}:project;}
function styleButtons(){return `<button class="style-card selected" data-action="style" data-value="kai" aria-pressed="true"><span class="style-thumb kai">kai.</span><span><strong>Kai · Little Makes</strong><small>DIY rumahan · teks Inggris singkat · Foley</small></span></button>`;}
function field(label,name,value,options={}){return `<div class="field"><label for="${name}">${label}</label>${options.area?`<textarea id="${name}" data-field="${name}" ${options.rows?`rows="${options.rows}"`:''} maxlength="${options.max||3000}">${esc(value)}</textarea>`:`<input id="${name}" data-field="${name}" type="${options.type||'text'}" value="${esc(value)}" ${options.min!==undefined?`min="${options.min}"`:''} ${options.max?`max="${options.max}"`:''} ${options.step?`step="${options.step}"`:''}>`}${options.help?`<small>${options.help}</small>`:''}</div>`;}
function selectField(label,name,value,values){return `<div class="field"><label for="${name}">${label}</label><select id="${name}" data-field="${name}">${values.map(v=>{const [id,title]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${String(value)===String(id)?'selected':''}>${esc(title)}</option>`;}).join('')}</select></div>`;}
function briefPanel(){return `<section class="panel inspector"><div class="panel-head"><h2>${icon('spark')}Creative brief</h2><span class="draft-badge">01 / MULAI DI SINI</span></div><div class="panel-body">${field('Ide DIY','topic',draft.topic,{area:true,max:500,help:'Barang apa yang dipakai, mau dijadikan apa, dan apa kegunaannya?'})}<div class="field-row">${field('Untuk siapa?','audience',draft.audience,{max:180})}${selectField('Cara bercerita','tone',draft.tone,['Calm, practical & warm'])}</div><div class="section-label">Pilih bahasa visual <small>Bisa diganti kapan saja</small></div><div class="style-grid">${styleButtons()}</div><div class="field"><label>Format video</label><div class="segments">${['9:16'].map(r=>`<button class="segment ${draft.aspectRatio===r?'selected':''}" data-action="ratio" data-value="${r}">${r==='9:16'?'▯':r==='16:9'?'▭':'□'} ${r}${r==='9:16'?' · Shorts':''}</button>`).join('')}</div></div><div class="field-row triple">${selectField('Durasi','duration',draft.duration,[8,15,30,45,60,90,120,180].map(n=>[n,`${n} detik`]))}${selectField('Klip Flow','clipDuration',draft.clipDuration,[[10,'10 detik'],[8,'8 detik'],[6,'6 detik'],[4,'4 detik']])}${selectField('Frame rate','fps',draft.fps,[[24,'24 fps'],[30,'30 fps']])}</div><p class="help">Durasi klip adalah target produksi. Hasil Flow dipotong sesuai timeline akhir.</p></div><div class="panel-footer"><button class="btn ghost" data-action="ideas">${icon('spark')}10 ide awal</button><button class="btn primary" data-action="apply-brief">Buat storyboard ${icon('arrow')}</button></div><div style="padding:12px 19px"><button class="text-link" data-action="codex">Brainstorm lebih jauh dengan Codex ${icon('external').replace('<svg','<svg style="width:11px;height:11px;vertical-align:middle"')}</button></div></section>`;}
function sceneTabs(){return `<div class="story-scenes" role="group" aria-label="Pilih scene">${project.scenes.map((s,i)=>`<button class="story-index ${i===selected?'active':''}" data-action="scene" data-index="${i}" aria-label="Scene ${i+1}" aria-pressed="${i===selected}">${String(i+1).padStart(2,'0')}</button>`).join('')}</div>`;}
function sceneNav(){return `<div class="scene-nav"><strong>Scene ${String(selected+1).padStart(2,'0')} <span> / ${project.scenes.length}</span></strong><span>${precise(sceneStart(selected))} — ${precise(sceneStart(selected)+scene().duration)}</span></div>`;}
function legacyStoryPanel(){const s=scene();return `<section class="panel inspector"><div class="panel-head"><h2>${icon('layers')}Storyboard</h2><button class="btn small ghost" data-action="copy-vo">${icon('copy')}Narasi</button></div><div class="panel-body">${sceneTabs()}${sceneNav()}${field('Headline di layar','scene-headline',s.headline,{max:160,help:'Singkat dan terbaca. Tipografi ditambahkan di editor.'})}${field('Voiceover','scene-voiceover',s.voiceover,{area:true,rows:3,max:3000})}${field('Arahan visual untuk Flow','scene-visual',s.visual,{area:true,rows:2,max:3000})}${field('Gerak & kamera untuk Flow','scene-motion',s.motion,{area:true,rows:2,max:3000})}${selectField('Objek motion bawaan','scene-graphic',s.graphic||'auto',[['auto','Otomatis per beat'],['steps','Anak tangga · kemajuan'],['timer','Timer · dua menit'],['bars','Grafik · proses'],['check','Centang · satu langkah'],['burst','Sunburst · mulai lagi']])}<div class="field-row">${field('Durasi scene (detik)','scene-duration',s.duration,{type:'number',min:.25,max:30,step:.25})}${selectField('Transisi ke berikutnya','scene-transition',s.transition,[['wipe','Graphic wipe'],['iris','Iris close'],['dissolve','Fade to color'],['cut','Hard cut']])}</div><div class="scene-actions"><button class="icon-btn" data-action="move-left" aria-label="Geser scene ke kiri" ${selected===0?'disabled':''}>${icon('left')}</button><button class="icon-btn" data-action="move-right" aria-label="Geser scene ke kanan" ${selected===project.scenes.length-1?'disabled':''}>${icon('chevron')}</button><button class="btn small ghost" data-action="duplicate">${icon('copy')}Duplikat</button><button class="icon-btn" data-action="delete-scene" aria-label="Hapus scene" ${project.scenes.length===1?'disabled':''}>${icon('trash')}</button></div><p class="studio-tips">Narasi memakai template offline. Edit di sini, atau impor JSON hasil brainstorming Codex.</p></div><div class="panel-footer"><button class="btn ghost" data-action="import-json">${icon('upload')}Impor JSON Codex</button><button class="btn primary" data-action="next">Ke Flow ${icon('arrow')}</button></div></section>`;}
function visualPrompt(){return buildImagePrompt(project,scene());}
function motionPrompt(){return buildAnimationPrompt(project,scene());}
function flowPanel(){const plan=generationPlan(scene(),project.brief);return `<section class="panel inspector"><div class="panel-head"><h2>${icon('spark')}Flow production pack</h2><a class="btn small ghost" href="https://labs.google/fx/tools/flow" target="_blank" rel="noopener noreferrer">Buka Flow ${icon('external')}</a></div><div class="panel-body"><div class="info-banner">${icon('info')}Buat keyframe di Flow, animasikan, lalu unduh klip dan impor ke scene. Pakai referensi visual yang sama untuk seluruh video.</div>${sceneTabs()}${sceneNav()}<div class="prompt-label">01 · KEYFRAME / IMAGE<button class="btn small ghost" data-action="copy-image">${icon('copy')}Salin</button></div><pre class="prompt-box">${esc(visualPrompt())}</pre><div class="scene-info"><strong>Timeline: ${scene().duration}s</strong> · bahan ${plan.clips} × ${plan.clipDuration}s · trim ${plan.trimStart}–${plan.trimEnd}s. ${plan.clips>1?'Gabungkan bahan berurutan sebelum diimpor sebagai satu file.':'Pilih durasi yang tersedia di Flow.'}</div><div class="prompt-label">02 · MOTION / VIDEO<button class="btn small ghost" data-action="copy-motion">${icon('copy')}Salin</button></div><pre class="prompt-box">${esc(motionPrompt())}</pre><p class="studio-tips">Teks dan audio ditambahkan terpisah di finishing. Kai memakai Foley dan room tone tanpa narator; durasi bahan dipotong sesuai timeline.</p></div><div class="panel-footer"><button class="btn ghost" data-action="flow-pack">${icon('download')}Semua prompt</button><button class="btn primary" data-action="next">Impor hasil ${icon('arrow')}</button></div></section>`;}
function audioRow(id,label,name){const a=asset(id);return `<div class="asset-row">${icon(name==='voice'?'mic':'music')}<span class="text"><strong>${esc(a?.name||label)}</strong><small>${a?'Tersimpan lokal · audio klip Flow dimatikan':'MP3, WAV, M4A, OGG · file lokal'}</small></span><button class="btn small ghost" data-action="upload-${name}">${a?'Ganti':'Tambah'}</button>${a?`<button class="icon-btn" data-action="remove-${name}" aria-label="Lepas ${label}">${icon('close')}</button>`:''}</div>`;}
function legacyEditPanel(){const s=scene(),a=asset(s.assetId);return `<section class="panel inspector"><div class="panel-head"><h2>${icon('film')}Media & finishing</h2><span class="status-tag">${project.scenes.filter(s=>s.assetId).length} / ${project.scenes.length} KLIP</span></div><div class="panel-body">${sceneTabs()}${sceneNav()}${a?`<div class="asset-row">${icon('film')}<span class="text"><strong>${esc(a.name)}</strong><small>${esc(a.type)} · ${(a.size/1024/1024).toFixed(1)} MB</small></span><button class="icon-btn" data-action="remove-media" aria-label="Lepas media scene">${icon('close')}</button></div>`:`<div class="scene-info"><strong>Motion dari kode</strong><br>Scene ini sudah bisa dirender. Tambahkan klip Flow jika ingin footage sebagai latar.</div>`}<button class="upload" data-action="upload-media">${icon('upload')}<strong>${a?'Ganti media scene':'Tambahkan hasil dari Flow'}</strong><small>MP4, WebM, MOV, PNG, JPG · maks. 250 MB</small></button><div class="field-row">${field('Mulai klip di (detik)','scene-trimStart',s.trimStart||0,{type:'number',min:0,max:86400,step:.1})}${field('Warna aksen','accent',project.brief.accent||palette(project.brief.style).accent,{type:'color'})}</div><p class="help">Footage mengisi frame, tipografi tetap di atasnya. Klip pendek ditahan pada frame akhir.</p><div class="divider"></div><div class="section-label">Suara yang menghidupkan cerita <small>Satu track per jenis</small></div>${audioRow(project.voiceoverAssetId,'Voiceover','voice')}${audioRow(project.musicAssetId,'Musik latar','music')}<div class="field"><label for="musicVolume">Volume musik <span id="volume-value" class="muted">${Math.round((project.musicVolume??.16)*100)}%</span></label><input id="musicVolume" data-field="musicVolume" type="range" min="0" max="1" step="0.01" value="${project.musicVolume??.16}"><small>Musik otomatis mengecil saat voiceover terdengar di hasil MP4.</small></div><label class="inline-check"><input type="checkbox" data-field="captions" ${captions?'checked':''}> Tampilkan caption yang mengikuti narasi</label><p class="studio-tips">Caption saat ini mengikuti proporsi kata per scene. Sesuaikan durasi scene dengan rekamanmu untuk timing yang lebih tepat.</p></div><div class="panel-footer"><button class="btn ghost" data-action="download-vo">${icon('download')}Naskah VO</button><button class="btn primary" data-action="next">Siapkan ekspor ${icon('arrow')}</button></div></section>`;}
function legacyExportPanel(){const errors=validateProject(project),words=project.scenes.map(s=>s.voiceover).join(' ').split(/\s+/).filter(Boolean).length;return `<section class="panel inspector"><div class="panel-head"><h2>${icon('download')}Render & delivery</h2><span class="status-tag">${health?.ffmpeg?'FFMPEG SIAP':'MEMERIKSA MESIN'}</span></div><div class="panel-body"><div class="stats"><div class="stat"><strong>${total().toFixed(total()%1?1:0)}<span style="font-size:12px">s</span></strong><small>DURASI AKHIR</small></div><div class="stat"><strong>${project.scenes.length}</strong><small>SCENE</small></div><div class="stat"><strong>${words}</strong><small>KATA NARASI</small></div></div><div class="field-row">${selectField('Resolusi','quality',Number(sessionStorage.getItem('motif-quality')||720),[[720,'720p · preview / cepat'],[1080,'1080p · master']])}<div class="field"><label>Format output</label><div class="scene-info" style="margin:0;padding:11px">H.264 / MP4 · ${project.brief.fps} fps</div></div></div>${errors.length?`<ul class="error-list">${errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul>`:''}<div id="render-status">${renderProgressHTML()}</div><p class="quality-note">Tetap buka tab saat render frame. Preview dan MP4 memakai mesin motion yang sama. ${project.voiceoverAssetId?'Voiceover akan dimasukkan.':'Tambahkan voiceover di Edit & audio untuk video bernarasi.'}</p><div class="divider"></div><div class="section-label">Bawa seluruh paketnya <small>Semua bisa diedit lagi</small></div><div class="export-grid"><button class="export-option" data-action="download-json">${icon('file')}<span><strong>Project JSON</strong><small>Backup / tukar dengan Codex</small></span></button><button class="export-option" data-action="production-pack">${icon('layers')}<span><strong>Production pack</strong><small>Naskah + prompt + metadata</small></span></button><button class="export-option" data-action="download-srt">${icon('file')}<span><strong>Subtitle .SRT</strong><small>Timing proporsi kata</small></span></button><button class="export-option" data-action="thumbnail">${icon('film')}<span><strong>Frame thumbnail</strong><small>PNG dari scene terpilih</small></span></button></div><div class="section-label">Ide judul <button class="text-link" data-action="publish-pack">Salin metadata</button></div>${(project.publishing?.titles||[project.title]).slice(0,3).map((title,i)=>`<div class="title-item"><span>0${i+1}</span>${esc(title)}</div>`).join('')}<p class="publish-title">${esc((project.publishing?.hashtags||[]).join(' '))}</p></div></section>`;}
function renderProgressHTML(){if(exporting){const status=renderStatus||{label:'Menyiapkan…',progress:0,detail:''};return `<div class="export-progress"><strong>${esc(status.label)}</strong><div class="progress-track"><i style="width:${clamp(status.progress)*100}%"></i></div><small>${esc(status.detail)}</small><button class="btn small ghost" data-action="cancel-export">Batalkan render</button></div>`;}if(renderJob?.status==='complete'){return `<div class="export-progress"><strong>${icon('check')} MP4 draft sudah jadi.</strong><a class="btn primary" href="${esc(renderJob.url)}" download>${icon('download')}Unduh video MP4</a><button class="text-link" data-action="render-video">Render ulang</button></div>`;}return `<button class="btn primary wide" data-action="render-video" ${health&&!health.ffmpeg?'disabled':''}>${icon('film')}Render draft MP4 ${icon('arrow')}</button>${renderStatus?.error?`<p class="status-error help">${esc(renderStatus.error)}</p>`:''}`;}
function previewPanel(){const p=effectiveProject(),c=palette(p.brief.style,p.brief.accent);return `<section class="panel preview-panel"><div class="panel-head"><h2>${icon('play')}Live preview</h2><div class="preview-tools"><small>${p.brief.aspectRatio} · ${p.brief.fps} FPS</small><button class="icon-btn ${safeArea?'active':''}" data-action="safe-area" aria-pressed="${safeArea}" title="Panduan safe area" aria-label="Panduan safe area">${icon('safe')}</button></div></div><div class="preview-stage ${p.brief.aspectRatio==='16:9'?'landscape':p.brief.aspectRatio==='1:1'?'square':''}"><span class="preview-badge">${styleNames[p.brief.style].toUpperCase()} / MOTION STUDY</span><canvas id="preview" width="540" height="960" aria-label="Preview motion video"></canvas></div><div class="preview-controls"><button id="play-button" class="play-btn" data-action="play" aria-label="${playing?'Jeda':'Putar'} preview">${icon(playing?'pause':'play')}</button><span class="timecode" id="timecode">${precise(time)} <span>/ ${tc(total())}</span></span><span class="spacer"></span><button class="icon-btn" data-action="restart" title="Kembali ke awal" aria-label="Kembali ke awal">${icon('undo')}</button><span class="chip" style="font-size:8px;padding:4px 6px">${p.brief.aspectRatio==='9:16'?'SHORTS / TIKTOK':p.brief.aspectRatio==='16:9'?'YOUTUBE':'SOCIAL'}</span></div><div class="seek-wrap"><input class="range" id="seek" type="range" min="0" max="${total()}" step="0.01" value="${time}" aria-label="Posisi preview"></div><div class="preview-note"><span>${route==='brief'?'Eksplorasi gaya · terapkan lewat Buat storyboard':'Tipografi + motion dari timeline'}</span><div class="mini-palette"><i style="background:${c.bg}"></i><i style="background:${c.fg}"></i><i style="background:${c.accent}"></i></div></div></section>`;}
function timelineHTML(){const p=palette(project.brief.style,project.brief.accent);return `<section class="panel timeline"><div class="timeline-head"><h2>${icon('layers')}Timeline <span class="muted" style="font-size:9px">${project.scenes.length} scene</span></h2><span class="meta"><span>MATERIAL → MAKE → USE</span><span>${total()}s / ${project.brief.fps} fps</span></span></div><div class="timeline-track">${project.scenes.map((s,i)=>`<button class="scene-tile ${selected===i?'active':''}" data-action="timeline-scene" data-index="${i}" aria-label="Pilih scene ${i+1}: ${esc(s.headline)}"><div class="scene-poster" style="background:${p.bg};color:${i%2?p.fg:p.accent}"><span class="scene-index">${String(i+1).padStart(2,'0')}</span><strong>${esc(s.headline)}</strong></div><div class="scene-meta"><span><i class="asset-dot ${s.assetId?'imported':''}"></i>${esc(s.label||`Scene ${i+1}`)}</span><span>${s.duration}s</span></div></button>`).join('')}</div><div class="timeline-audio">${icon('music')}<span>${isKai(project)?'Room tone + suara bahan · finishing otomatis':project.voiceoverAssetId?'Voiceover terpasang':'Tambahkan suara ke ceritamu'}</span><span class="waveform" aria-hidden="true">${Array.from({length:80},(_,i)=>`<i style="height:${4+(Math.sin(i*1.9)+1)*5+(i%3)*2}px"></i>`).join('')}</span><button class="btn small ghost" data-action="audio-tab">${icon('plus')}Audio</button></div></section>`;}
function render(){if(unmountAutopilot){unmountAutopilot();unmountAutopilot=null;}const stage=stages.find(s=>s[0]===route);selected=Math.min(selected,project.scenes.length-1);$('#app').innerHTML=`<div class="app"><aside class="sidebar"><a class="logo" href="#" data-action="home" aria-label="Kai Makes Do studio"><span class="logo-mark kai-dot"></span><span class="logo-name">kai makes do.<span>LITTLE MAKES STUDIO</span></span></a><button class="project-switch" data-action="projects"><span class="project-icon">${icon('folder')}</span><span class="text"><strong>${esc(project.title)}</strong><small>WORKSPACE LOKAL</small></span>${icon('down')}</button><nav aria-label="Tahap produksi"><p class="nav-label">AUTO + CREATIVE CONTROL</p><div class="steps">${stages.map((s,i)=>`<button class="nav-item ${route===s[0]?'active':''}" data-action="route" data-value="${s[0]}" ${route===s[0]?'aria-current="step"':''}><span class="number">${i+1}</span><span>${s[1]}</span></button>`).join('')}</div></nav><div class="sidebar-bottom"><div class="side-note"><strong>${icon('spark')}Small ideas.</strong>Everyday stuff.<br>A little more useful.</div><div class="side-links"><button data-action="help">Panduan ${icon('external').replace('<svg','<svg style="width:10px;height:10px;vertical-align:middle"')}</button><span>v1.0 / LOCAL</span></div></div></aside><main class="main"><header class="topbar"><div class="crumb"><span>Workspace</span><span>/</span><button class="icon-btn" data-action="projects" aria-label="Proyek tersimpan">${icon('folder')}</button><input class="project-name-input" id="project-title" aria-label="Nama proyek" value="${route==='autopilot'?'Kai / Little Makes 9:16':esc(project.title)}" ${route==='autopilot'?'readonly':''} maxlength="200"></div><div class="top-actions"><span id="save-state" class="save-state"><i class="dot"></i>Tersimpan lokal</span>${route==='autopilot'?'':`<button class="btn ghost" data-action="download-json">${icon('download')}Project</button>`}<button class="btn primary" data-action="${route==='autopilot'?'editor-tab':'export-tab'}">${route==='autopilot'?'Editor lanjutan':'Ekspor draft'} ${icon('arrow')}</button></div></header><div class="workspace"><div class="workspace-heading"><div><div class="eyebrow">${String(stages.indexOf(stage)+1).padStart(2,'0')} / ${stage[1]}</div><h1>${stage[2]}</h1><p>${stage[3]}</p></div><span class="chip"><i class="dot"></i> LITTLE HOME IDEAS</span></div>${route==='autopilot'?'<div id="autopilot-root"></div>':`<div class="workbench">${route==='brief'?briefPanel():route==='storyboard'?storyPanel():route==='flow'?flowPanel():route==='edit'?editPanel():exportPanel()}${previewPanel()}</div>${timelineHTML()}`}<div class="footer-caption"><span>SMALL IDEAS. EVERYDAY STUFF.</span><span>CODEX → FLOW FOOTAGE → MOTION FINISHING · 9:16</span></div></div></main></div>`;bindInputs();if(route==='autopilot')unmountAutopilot=mountAutopilot($('#autopilot-root'),{brief:{...defaults,aspectRatio:'9:16'},notify:toast,onOpenProject:p=>{pause();project=p;draft={...p.brief};selected=0;time=.85;captions=p.captions!==false;route='storyboard';renderJob=savedRender(p);markDirty();render();}});syncCanvas();updateSave();if(exporting)setLocked(true);}
function setRoute(value){if(exporting)return toast('Selesaikan atau batalkan render dulu.');if(route==='brief'&&['topic','audience','tone','duration'].some(k=>draft[k]!==project.brief[k]))toast('Brief berubah. Buat storyboard untuk menerapkannya; timeline sekarang tetap '+total()+' detik.');pause();route=value;render();}
function pickScene(index){pause();selected=clamp(index,0,project.scenes.length-1);time=Math.min(total()-.001,sceneStart(selected)+Math.min(.85,scene().duration/2));render();}
function bindInputs(){document.querySelectorAll('[data-field]').forEach(el=>el.addEventListener('change',()=>fieldChange(el)));$('#project-title').addEventListener('change',event=>{const value=event.target.value.trim();if(value){project.title=value;renderJob=null;markDirty();}else event.target.value=project.title;});$('#seek')?.addEventListener('input',event=>{pause();time=Number(event.target.value);syncCanvas();});}
function fieldChange(el){const key=el.dataset.field;try{
  if(key==='quality'){sessionStorage.setItem('motif-quality',el.value);return;}
  if(key.startsWith('scene-')){const prop=key.slice(6),previous=scene()[prop];let value=el.value;if(['duration','trimStart'].includes(prop)){value=Number(value);if(!Number.isFinite(value)||value<Number(el.min)||value>Number(el.max))throw Error('Angka di luar rentang.');}scene()[prop]=value;const duration=total();if(duration>180||duration<8){scene()[prop]=previous;throw Error('Durasi total harus 8–180 detik.');}project.brief.duration=Number(duration.toFixed(3));draft={...project.brief};renderJob=null;markDirty();render();}
  else if(key==='accent'){project.brief.accent=el.value;draft.accent=el.value;renderJob=null;markDirty();syncCanvas();}
  else if(key==='musicVolume'){project.musicVolume=Number(el.value);if(audio.music)audio.music.volume=project.musicVolume;markDirty();$('#volume-value').textContent=Math.round(project.musicVolume*100)+'%';renderJob=null;}
  else if(key==='captions'){captions=el.checked;project.captions=captions;renderJob=null;markDirty();syncCanvas();}
  else {draft[key]=['duration','fps','clipDuration'].includes(key)?Number(el.value):el.value;if(['fps','clipDuration'].includes(key)){project.brief[key]=draft[key];renderJob=null;markDirty();render();}}
}catch(error){toast(error.message,true);render();}}
function syncCanvas(){const canvas=$('#preview');if(!canvas)return;const p=effectiveProject(),d=dimensions(p.brief.aspectRatio,540);if(canvas.width!==d.width||canvas.height!==d.height){canvas.width=d.width;canvas.height=d.height;}const active=sceneAt(project,Math.min(time,total()-.00001));const media=getMedia(active.scene?.assetId);if(media?.tagName==='VIDEO'&&!exporting){const target=mediaTime(active.scene,active.local,media);if(!media.seeking&&Math.abs(media.currentTime-target)>.08)media.currentTime=target;}drawFrame(canvas,p,time,{safeArea,captions,media:media?.readyState>=2||media?.complete?media:null});$('#timecode').innerHTML=`${precise(time)} <span>/ ${tc(total())}</span>`;$('#seek').value=time;}
function getMedia(id){if(!id)return null;if(cache.has(id))return cache.get(id);const a=asset(id);if(!a)return null;const media=a.type.startsWith('image/')?new Image():document.createElement('video');cache.set(id,media);if(media.tagName==='VIDEO'){media.muted=true;media.playsInline=true;media.preload='auto';media.addEventListener('seeked',()=>{if(!exporting)syncCanvas();});media.addEventListener('loadeddata',()=>syncCanvas());media.addEventListener('error',()=>toast(`Media gagal dibaca: ${a.name}`,true));}else {media.onload=()=>syncCanvas();media.onerror=()=>toast(`Gambar gagal dibaca: ${a.name}`,true);}media.src=a.url;return media;}
function mediaTime(s,local,media){return clamp((s.trimStart||0)+local,0,Number.isFinite(media.duration)?Math.max(0,media.duration-.045):local);}
function pause(){playing=false;for(const media of Object.values(audio))media?.pause();const b=$('#play-button');if(b){b.innerHTML=icon('play');b.setAttribute('aria-label','Putar preview');}}
function prepareAudio(){for(const [name,key] of [['voice','voiceoverAssetId'],['music','musicAssetId']]){const a=asset(project[key]);if(!a){audio[name]?.pause();audio[name]=null;continue;}if(!audio[name]||audio[name].dataset.id!==a.id){audio[name]?.pause();audio[name]=new Audio(a.url);audio[name].dataset.id=a.id;audio[name].loop=name==='music';}audio[name].volume=name==='music'?(project.musicVolume??.16):1;}}
function togglePlay(){if(exporting)return;if(playing){pause();return;}if(time>=total()-.05)time=0;playing=true;prepareAudio();for(const a of Object.values(audio)){if(a){a.currentTime=Number.isFinite(a.duration)&&a.loop?time%a.duration:time;a.play().catch(()=>{});}}const startTime=time,start=performance.now();$('#play-button').innerHTML=icon('pause');$('#play-button').setAttribute('aria-label','Jeda preview');function tick(now){if(!playing)return;time=Math.min(total(),startTime+(now-start)/1000);syncCanvas();if(time>=total())pause();else requestAnimationFrame(tick);}requestAnimationFrame(tick);}
async function applyBrief(idea){pause();await saveProject().catch(()=>{});project=createProject(normalizeBrief(draft),idea);draft={...project.brief};selected=0;time=.85;captions=project.captions!==false;renderJob=null;route='storyboard';cache.clear();markDirty();render();toast('Storyboard siap. Cek urutan proses dan kegunaan hasilnya.');}
function ideasModal(){const ideas=generateIdeas(draft);showModal('Cari sudut yang terasa dekat.',`<p>10 titik awal dari template offline. Pilih satu untuk membuat storyboard, atau lanjutkan brainstorming bersama Codex.</p><div class="idea-list">${ideas.map((idea,i)=>`<button class="idea-choice" data-action="choose-idea" data-index="${i}"><span class="n">${String(i+1).padStart(2,'0')}</span><span><strong>${esc(idea.title)}</strong><small>${esc(idea.hook)}</small></span></button>`).join('')}</div>`);window.__motifIdeas=ideas;}
function codexModal(){showModal('Lanjutkan bareng Codex.',`<p>Salin brief ini ke chat Codex. Minta ide, narasi, dan storyboard yang lebih spesifik, lalu impor JSON hasilnya lewat tombol di bawah.</p><pre class="prompt-box">${esc(buildCodexPrompt(draft))}</pre><div class="modal-actions"><button class="btn primary" data-action="copy-codex">${icon('copy')}Salin brief Codex</button><button class="btn ghost" data-action="import-json">${icon('upload')}Impor JSON</button></div>`);}
async function showProjects(){pause();await saveProject().catch(()=>{});const {projects}=await api('/api/projects');showModal('Ruang untuk ide berikutnya.',`<p>Proyek tersimpan di komputer ini. Ekspor JSON untuk dipindahkan ke perangkat lain.</p><div class="project-list">${projects.map(p=>`<button class="project-entry" data-action="open-project" data-id="${esc(p.id)}"><strong>${esc(p.title)}</strong><small>${p.sceneCount} scene · ${p.duration}s</small></button>`).join('')||'<p class="empty">Belum ada proyek tersimpan.</p>'}</div><div class="modal-actions"><button class="btn primary" data-action="new-project">${icon('plus')}Proyek baru</button><button class="btn ghost" data-action="help">${icon('info')}Panduan studio</button></div>`);}
async function importJson(file){if(file.size>2*1024*1024)throw Error('Ukuran JSON maksimal 2 MB.');const value=JSON.parse(await file.text());if(value?.brief?.aspectRatio!=='9:16')throw Error('Studio ini memakai video vertikal 9:16. Ubah rasio project JSON ke 9:16.');const errors=validateProject(value);if(errors.length)throw Error(errors.slice(0,3).join(' '));await saveProject().catch(()=>{});pause();project=value;project.id=crypto.randomUUID();draft={...project.brief};captions=project.captions!==false;selected=0;time=.85;route='storyboard';renderJob=null;cache.clear();modalClose();markDirty();render();toast('JSON masuk. Storyboard siap diedit.');}
function pickFile(accept,handler){const input=document.createElement('input');input.type='file';input.accept=accept;input.className='file-input';document.body.append(input);input.addEventListener('change',async()=>{const f=input.files[0];input.remove();if(f)try{await handler(f);}catch(error){toast(error.message,true);}});input.addEventListener('cancel',()=>input.remove());input.click();}
async function uploadMedia(kind){const accept=kind==='media'?'video/mp4,video/webm,video/quicktime,image/png,image/jpeg,image/webp':'audio/mpeg,audio/wav,audio/x-wav,audio/mp4,audio/ogg,audio/aac,audio/flac,audio/webm';pickFile(accept,async file=>{if(file.size>250*1024*1024)throw Error('Ukuran file maksimal 250 MB.');const targetScene=scene(),targetProject=project;toast('Menyimpan media di perangkat…');const type=file.type||({mp4:'video/mp4',webm:'video/webm',mov:'video/quicktime',mp3:'audio/mpeg',wav:'audio/wav',m4a:'audio/mp4',flac:'audio/flac',ogg:'audio/ogg',aac:'audio/aac'}[file.name.split('.').pop().toLowerCase()]);const result=await api(`/api/assets?name=${encodeURIComponent(file.name)}`,{method:'POST',headers:{'Content-Type':type||'application/octet-stream'},body:file});if(project!==targetProject)return;project.assets||=[];project.assets.push(result);if(kind==='media'){targetScene.assetId=result.id;targetScene.trimStart=0;}else project[kind==='voice'?'voiceoverAssetId':'musicAssetId']=result.id;renderJob=null;markDirty();render();toast('Media ditambahkan.');});}
async function waitForMedia(media){if(media.tagName==='IMG'&&media.complete&&media.naturalWidth)return;if(media.tagName==='VIDEO'&&media.readyState>=2)return;await new Promise((resolve,reject)=>{const done=()=>{clearTimeout(timer);media.removeEventListener('error',fail);resolve();},fail=()=>{clearTimeout(timer);reject(Error('Media tidak dapat dibaca. Coba MP4 H.264 atau PNG/JPG.'));},timer=setTimeout(()=>reject(Error('Media terlalu lama dimuat.')),20000);media.addEventListener(media.tagName==='IMG'?'load':'loadeddata',done,{once:true});media.addEventListener('error',fail,{once:true});});}
async function seekMedia(media,target){if(media.tagName!=='VIDEO'||Math.abs(media.currentTime-target)<.0001)return;await new Promise((resolve,reject)=>{const done=()=>{clearTimeout(timer);media.removeEventListener('error',fail);resolve();},fail=()=>{clearTimeout(timer);reject(Error('Klip gagal diposisikan.'));},timer=setTimeout(()=>reject(Error('Klip terlalu lama diposisikan. Coba konversi ke MP4 H.264.')),10000);media.addEventListener('seeked',done,{once:true});media.addEventListener('error',fail,{once:true});media.currentTime=target;});}
const blobFromCanvas=(canvas,type='image/jpeg',quality=.92)=>new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(Error('Frame gagal dibuat.')),type,quality));
function setLocked(locked){$('#app').querySelectorAll('button,input,select,textarea').forEach(el=>{if(el.dataset.action!=='cancel-export')el.disabled=locked;});}
function updateRenderStatus(value){renderStatus=value;if($('#render-status'))$('#render-status').innerHTML=renderProgressHTML();}
async function renderVideo(){if(exporting)return;const errors=validateProject(project);if(errors.length)return toast(errors[0],true);if(!health?.ffmpeg)return toast('FFmpeg belum tersedia. Jalankan npm run setup:ffmpeg lalu restart studio.',true);pause();route='export';renderJob=null;renderStatus=null;exporting=true;cancelExport=false;render();setLocked(true);const snapshot=structuredClone(project),quality=Number(sessionStorage.getItem('motif-quality')||720),d=dimensions(snapshot.brief.aspectRatio,quality),canvas=document.createElement('canvas');canvas.width=d.width;canvas.height=d.height;let job;
  try{await saveProject();job=await post('/api/renders',{project:snapshot,...d,fps:snapshot.brief.fps});renderJob=job;
    for(let frame=0;frame<job.totalFrames;frame++){
      if(cancelExport)throw Error('Render dibatalkan.');const t=frame/job.fps,{scene:s,local}=sceneAt(snapshot,t);let media=null;
      if(s.assetId){media=getMedia(s.assetId);if(!media)throw Error('Media scene tidak ditemukan. Impor ulang file lokalnya.');await waitForMedia(media);await seekMedia(media,mediaTime(s,local,media));}
      drawFrame(canvas,snapshot,t,{captions:snapshot.captions!==false,media});
      const blob=await blobFromCanvas(canvas);await api(`/api/renders/${job.id}/frame?index=${frame}`,{method:'POST',headers:{'Content-Type':'image/jpeg'},body:blob});
      if(frame%6===0||frame===job.totalFrames-1){time=t;syncCanvas();updateRenderStatus({label:`Membuat frame · ${Math.round((frame+1)/job.totalFrames*100)}%`,progress:(frame+1)/job.totalFrames*.8,detail:`${frame+1} / ${job.totalFrames} frame · ${d.width} × ${d.height} · ${job.fps} fps`});}
    }
    if(cancelExport)throw Error('Render dibatalkan.');await post(`/api/renders/${job.id}/finish`,{});
    while(true){if(cancelExport)throw Error('Render dibatalkan.');const next=await api(`/api/renders/${job.id}`);if(next.status==='complete'){renderJob={...next,fingerprint:fingerprint(snapshot)};project.lastRender=renderJob;markDirty();break;}if(next.status==='error'||next.status==='cancelled')throw Error(next.error||'Render dibatalkan.');updateRenderStatus({label:'FFmpeg sedang menyatukan video…',progress:.8+next.progress*.2,detail:'H.264 + audio · musik ducking otomatis jika ada voiceover'});await new Promise(resolve=>setTimeout(resolve,700));}
    toast('MP4 draft selesai. Untuk hasil Flow lengkap, gunakan Produksi otomatis.');
  }catch(error){if(job&&renderJob?.status!=='complete')await post(`/api/renders/${job.id}/cancel`,{}).catch(()=>{});renderStatus={error:error.message};renderJob=null;toast(error.message,true);}
  finally{exporting=false;cancelExport=false;time=.85;render();}
}
async function thumbnail(){pause();const canvas=document.createElement('canvas'),d=dimensions(project.brief.aspectRatio,1080);canvas.width=d.width;canvas.height=d.height;const s=scene(),media=getMedia(s.assetId);if(media){await waitForMedia(media);await seekMedia(media,mediaTime(s,Math.min(.85,s.duration/2),media));}drawFrame(canvas,project,sceneStart(selected)+Math.min(.85,s.duration/2),{media,captions:false});const blob=await blobFromCanvas(canvas,'image/png'),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${slug()}-scene-${selected+1}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Frame PNG diekspor sesuai rasio proyek.');}
function recompute(){project.brief.duration=Number(total().toFixed(3));draft={...project.brief};selected=Math.min(selected,project.scenes.length-1);time=Math.min(total()-.001,sceneStart(selected)+.85);renderJob=null;markDirty();render();}
function publishingText(){const p=project.publishing||{};return `JUDUL\n${(p.titles||[project.title]).map((t,i)=>`${i+1}. ${t}`).join('\n')}\n\nDESKRIPSI\n${p.description||''}\n\nHASHTAGS\n${(p.hashtags||[]).join(' ')}\n\nTHUMBNAIL PROMPT\n${p.thumbnailPrompt||''}`;}
async function action(name,el){if(exporting&&name!=='cancel-export')return;switch(name){
case 'editor-tab':return setRoute('brief');case 'route':return setRoute(el.dataset.value);case 'home':return setRoute('autopilot');case 'next':return setRoute(stages[Math.min(stages.length-1,stages.findIndex(s=>s[0]===route)+1)][0]);case 'export-tab':return setRoute('export');case 'audio-tab':return setRoute('edit');case 'style':draft.style=el.dataset.value;draft.accent=palette(draft.style).accent;project.brief.style=draft.style;project.brief.accent=draft.accent;renderJob=null;markDirty();return render();case 'ratio':draft.aspectRatio=el.dataset.value;project.brief.aspectRatio=draft.aspectRatio;renderJob=null;markDirty();return render();case 'scene':case 'timeline-scene':return pickScene(Number(el.dataset.index));case 'play':return togglePlay();case 'restart':pause();time=0;return syncCanvas();case 'safe-area':safeArea=!safeArea;return render();case 'apply-brief':return applyBrief();case 'ideas':return ideasModal();case 'choose-idea':{const idea=window.__motifIdeas[Number(el.dataset.index)];modalClose();return applyBrief(idea);}case 'codex':return codexModal();case 'copy-codex':return copy(buildCodexPrompt(draft));case 'copy-image':return copy(visualPrompt());case 'copy-motion':return copy(motionPrompt());case 'copy-vo':return copy(project.scenes.map(s=>s.voiceover).join('\n\n'));case 'download-vo':return download(`${slug()}-voiceover.txt`,project.scenes.map(s=>s.voiceover).join('\n\n'));case 'flow-pack':return download(`${slug()}-flow-prompts.md`,buildFlowPack(project));case 'production-pack':return download(`${slug()}-production.md`,exportProjectMarkdown(project));case 'download-json':return download(`${slug()}.json`,JSON.stringify(project,null,2),'application/json');case 'download-srt':return download(`${slug()}.srt`,toSrt(project),'application/x-subrip');case 'publish-pack':return copy(publishingText());case 'thumbnail':return thumbnail();case 'projects':return showProjects();case 'close-modal':return modalClose();case 'import-json':return pickFile('.json,application/json',importJson);case 'new-project':pause();await saveProject().catch(()=>{});project=createProject(defaults);draft={...project.brief};captions=project.captions!==false;selected=0;time=.85;route='brief';cache.clear();renderJob=null;modalClose();markDirty();return render();case 'open-project':{pause();const result=await api(`/api/projects/${el.dataset.id}`);project=result.project;project.brief.aspectRatio='9:16';draft={...project.brief};captions=project.captions!==false;route='storyboard';selected=0;time=.85;renderJob=savedRender(project);cache.clear();modalClose();markDirty();return render();}case 'upload-media':return uploadMedia('media');case 'upload-voice':return uploadMedia('voice');case 'upload-music':return uploadMedia('music');case 'remove-media':scene().assetId=null;scene().trimStart=0;renderJob=null;markDirty();return render();case 'remove-voice':project.voiceoverAssetId=null;pause();markDirty();renderJob=null;return render();case 'remove-music':project.musicAssetId=null;pause();markDirty();renderJob=null;return render();case 'duplicate':if(total()+scene().duration>180||project.scenes.length>=60)return toast('Batas: 180 detik / 60 scene.',true);{const s=structuredClone(scene());s.id=crypto.randomUUID();project.scenes.splice(selected+1,0,s);selected++;return recompute();}case 'delete-scene':if(total()-scene().duration<8)return toast('Durasi proyek minimal 8 detik. Panjangkan scene lain sebelum menghapus.',true);if(project.scenes.length>1){project.scenes.splice(selected,1);recompute();}return;case 'move-left':if(selected>0){[project.scenes[selected],project.scenes[selected-1]]=[project.scenes[selected-1],project.scenes[selected]];selected--;recompute();}return;case 'move-right':if(selected<project.scenes.length-1){[project.scenes[selected],project.scenes[selected+1]]=[project.scenes[selected+1],project.scenes[selected]];selected++;recompute();}return;case 'render-video':return renderVideo();case 'cancel-export':cancelExport=true;toast('Membatalkan render…');return;case 'help':return showModal('Kai Makes Do · cara kerja',`<p>Masukkan ide DIY dan batas kredit di Produksi otomatis. Codex menyusun material → proses → hasil yang dipakai; Flow membuat footage vertikal, lalu finishing menambahkan teks Inggris singkat dan sound design.</p><p>Kai tampil konsisten dengan kaus sage, cahaya alami dan meja rumah biasa. Tanpa narator, caption karaoke, nomor episode atau label AI di frame. Konteks karakter AI ada pada metadata publikasi.</p><p>Editor lanjutan untuk studi motion dan revisi. Draft tanpa footage bukan produksi Flow selesai. Klip, kredit dan arsip proyek lama tetap disimpan.</p>`);
case 'legacy-help':return showModal('Dari satu ide ke video pendek.',`<p><strong>1. Brief.</strong> Pilih pesan, audiens, durasi, dan gaya. Gunakan ide offline atau salin brief untuk brainstorming lebih jauh dengan Codex.</p><p><strong>2. Storyboard.</strong> Edit headline, narasi, visual, dan gerak per scene. Impor JSON hasil Codex untuk cerita yang lebih spesifik.</p><p><strong>3. Flow.</strong> Salin prompt keyframe dan motion. Generate di akun Flow milikmu, lalu unduh hasilnya. Tiap scene memiliki target durasi; kelebihan klip akan dipotong saat editing.</p><p><strong>4. Edit.</strong> Impor hasil Flow ke scene, tambahkan rekaman voiceover dan musik. Semua media disimpan lokal. Scene tanpa klip memakai motion dari kode.</p><p><strong>5. Ekspor.</strong> Render MP4, unduh subtitle, frame PNG, JSON, dan paket produksi. Simpan salinan JSON serta file media untuk cadangan.</p><div class="info-banner">Proyek ini tidak terhubung langsung ke API Codex atau Flow. Mengedit dan merender motion kode berjalan lokal, tanpa biaya generasi.</div><p><a class="text-link" href="https://github.com/remotion-dev/skills" target="_blank" rel="noopener noreferrer">Remotion skills</a> · <a class="text-link" href="https://github.com/heygen-com/hyperframes" target="_blank" rel="noopener noreferrer">HyperFrames</a></p>`);
}}
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;event.preventDefault();Promise.resolve(action(el.dataset.action,el)).catch(error=>toast(error.message,true));});
document.addEventListener('keydown',event=>{if(event.code==='Space'&&!['INPUT','TEXTAREA','SELECT','BUTTON'].includes(event.target.tagName)&&!$('#modal').open){event.preventDefault();togglePlay();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&playing)pause();});
window.addEventListener('beforeunload',event=>{if(exporting){event.preventDefault();event.returnValue='Render belum selesai.';}});
render();
api('/api/health').then(value=>{health=value;if(route==='export')render();}).catch(error=>toast('Server studio tidak terhubung: '+error.message,true));
markDirty();

function storyPanel(){if(!isKai(project))return legacyStoryPanel();const s=scene();return `<section class="panel inspector"><div class="panel-head"><h2>Material → Make → Use</h2><span class="status-tag">KAI / SILENT DIY</span></div><div class="panel-body">${sceneTabs()}${sceneNav()}${field('Teks Inggris di layar · boleh kosong','scene-headline',s.headline,{max:80,help:'Hook singkat di awal; satu catatan praktis saat proses; penutup sederhana.'})}${field('Proses & material untuk Flow','scene-visual',s.visual,{area:true,rows:5,max:3000})}${field('Gerak & kamera','scene-motion',s.motion,{area:true,rows:3,max:3000})}<div class="field-row">${field('Durasi scene','scene-duration',s.duration,{type:'number',min:.25,max:30,step:.25})}${selectField('Transisi','scene-transition',s.transition,[['cut','Clean cut'],['dissolve','Gentle dissolve']])}</div><p class="studio-tips">Kai: kaus sage, meja rumah, cahaya dari kiri. Tunjukkan tahap nyata, jeda pengeringan bila perlu, lalu hasil dipakai. Tanpa narator atau klaim durasi pengerjaan.</p></div><div class="panel-footer"><button class="btn ghost" data-action="import-json">Impor JSON</button><button class="btn primary" data-action="next">Prompt Flow →</button></div></section>`;}
function editPanel(){if(!isKai(project))return legacyEditPanel();const s=scene(),a=asset(s.assetId);return `<section class="panel inspector"><div class="panel-head"><h2>Footage & sound</h2><span class="status-tag">LITTLE MAKES</span></div><div class="panel-body">${sceneTabs()}${sceneNav()}<p class="help">${a?esc(a.name):'Studi motion lokal. Tambahkan footage Flow untuk produksi sebenarnya.'}</p><button class="upload" data-action="upload-media">${icon('upload')}<strong>${a?'Ganti klip':'Tambahkan hasil Flow'}</strong><small>Footage vertikal 9:16</small></button>${field('Trim awal klip (detik)','scene-trimStart',s.trimStart||0,{type:'number',min:0,max:86400,step:.1})}<div class="divider"></div><h3>Quiet, tactile, everyday.</h3><p class="help">Produksi otomatis membuat room tone dan tekstur suara bahan. Posisi cue awal diperkirakan dari scene; cek sinkronisasinya setelah footage ada. Musik instrumental opsional, tanpa suara narator.</p>${audioRow(project.musicAssetId,'Musik instrumental opsional','music')}<div class="field"><label for="musicVolume">Volume musik <span id="volume-value">${Math.round((project.musicVolume??0)*100)}%</span></label><input id="musicVolume" data-field="musicVolume" type="range" min="0" max=".3" step=".01" value="${project.musicVolume??0}"></div><p class="studio-tips">Opening 2,5 detik → proses bersih → reveal 3 detik. Nomor episode dan label AI tidak tampil pada video.</p></div><div class="panel-footer"><button class="btn primary" data-action="next">Siapkan ekspor →</button></div></section>`;}
function exportPanel(){if(!isKai(project))return legacyExportPanel();return `<section class="panel inspector"><div class="panel-head"><h2>Review & delivery</h2><span class="status-tag">9:16 / KAI</span></div><div class="panel-body"><p class="help">Ini ekspor draft editor. MP4 produksi lengkap dengan sound design tersedia melalui Produksi otomatis setelah seluruh footage Flow diterima.</p><div class="stats"><div class="stat"><strong>${total()}s</strong><small>DURASI</small></div><div class="stat"><strong>${project.scenes.length}</strong><small>SCENE</small></div><div class="stat"><strong>9:16</strong><small>VERTIKAL</small></div></div>${selectField('Resolusi draft','quality',Number(sessionStorage.getItem('motif-quality')||720),[[720,'720p · preview'],[1080,'1080p · master']])}${renderProgressHTML()}<div class="divider"></div><div class="export-grid"><button class="export-option" data-action="download-json">Project JSON</button><button class="export-option" data-action="production-pack">Paket produksi</button><button class="export-option" data-action="thumbnail">Frame PNG</button><button class="export-option" data-action="publish-pack">Metadata publish</button></div>${(project.publishing?.titles||[]).map(title=>`<p class="publish-title">${esc(title)}</p>`).join('')}</div></section>`;}
document.fonts.ready.then(()=>syncCanvas());
